internal class GUPPriceTermEnableDisable extends RunBaseBatch
{
    GUPCheckEnableDisable operationType;
    GUPPriceTermJournalTable journalTable;

    GUPPriceTermEnableDisableErrorList errorList;

    boolean isValid = true;

    Integer         logPoint;

    #define.CurrentVersion(90)    
    #localmacro.CurrentList
        operationType,
        journalTable
    #endmacro

}

Method.Source:
public ClassDescription caption()
{
    if (operationType == GUPCheckEnableDisable::Check)
    {
        return strFmt("@GlobalUnifiedPricing:GUPPriceTermEnableDisable_Caption_Check", this.journalTable.AgreementId);
    }
    else if (operationType == GUPCheckEnableDisable::Disable)
    {
        return strFmt("@GlobalUnifiedPricing:GUPPriceTermEnableDisable_Caption_Disable", this.journalTable.AgreementId);
    }
    else
    {
        return strFmt("@GlobalUnifiedPricing:GUPPriceTermEnableDisable_Caption_Enable", this.journalTable.AgreementId);
    }
}

public client server static ClassDescription description()
{
    return "@GlobalUnifiedPricing:GUPPriceTermEnableDisable_description";
}

protected boolean canGoBatchJournal()
{
    return true;
}

public boolean allowSaveLast()
{
    return false;
}

protected DialogRunbase dialogPostInit(DialogRunbase dialog)
{
    DialogRunbase ret;

    ret = super(dialog);

    return ret;
}

public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

public boolean unpack(container _packedClass)
{
    boolean  ret;
    Integer  version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList] = _packedClass;
            ret = true;
            break;

        default :
            ret = false;
    }

    return ret;
}

protected boolean allowTransferErrors()
{
    return true;
}

protected boolean hasChangedErrorList()
{
    return true;
}

public boolean canGoBatch()
{
    return true;
}

public boolean runsImpersonated()
{
    return true;
}

protected boolean canRunInNewSession()
{
    return true;
}

public static void main(Args args)
{
    GUPPriceTermEnableDisable enableDisable = GUPPriceTermEnableDisable::construct(args);
    enableDisable.runOperation();
}

public Integer logPoint(Integer _logPoint = logPoint)
{
    logPoint  = _logPoint;
    return logPoint;
}

public void initFromArgs(Args _args)
{
    journalTable = _args.record();
    operationType = _args.parmEnum();
}

public static GUPPriceTermEnableDisable construct(Args _args)
{
    GUPPriceTermEnableDisable   gupPriceTermEnableDisable = new GUPPriceTermEnableDisable();
    gupPriceTermEnableDisable.initFromArgs(_args);

    return gupPriceTermEnableDisable;
}

public void new()
{
    super();
}

public final void run()
{
    boolean ret;

    errorList = new GUPPriceTermEnableDisableErrorList(journalTable);
    logPoint = infologLine();

    setPrefix(errorList.prefixJournalTable(journalTable.AgreementId));

    switch (operationType)
    {
        case GUPCheckEnableDisable::Check:
            ret = this.checkJournal();
            if (ret)
            {
                info(strFmt("@GlobalUnifiedPricing:GUPPriceTermEnableDisable_Check_Succeed", journalTable.AgreementId));
            }
            else
            {
                warning(strFmt("@GlobalUnifiedPricing:GUPPriceTermEnableDisable_Check_Fail", journalTable.AgreementId));
            }
            break;
        case GUPCheckEnableDisable::Enable:
            ret = this.checkJournal();
            if (ret)
            {
                this.updateJournalStatus(GUPDisabledEnabled::Enabled);
                info(strFmt("@GlobalUnifiedPricing:GUPPriceTermEnableDisable_Enabled", journalTable.AgreementId));
            }
            else
            {
                warning(strFmt("@GlobalUnifiedPricing:GUPPriceTermEnableDisable_Check_Fail", journalTable.AgreementId));
            }
            break;
        case GUPCheckEnableDisable::Disable:
            this.updateJournalStatus(GUPDisabledEnabled::Disabled);
            info(strFmt("@GlobalUnifiedPricing:GUPPriceTermEnableDisable_Disabled", journalTable.AgreementId));
            break;
    }
}

public static Integer infologPack(Integer  _logPoint)
{
    container               c;
    Integer                 line;
    Exception               exceptionNow;
    Exception               exceptionHigh;
    SysInfologEnumerator    enum;
    SysInfoAction           sysInfoAction = null;

    line = infologLine();

    c = infolog.cut(_logPoint+1, line);
    enum = SysInfologEnumerator::newData(c);

    while (enum.moveNext())
    {
        exceptionNow = enum.currentException();
        if (exceptionNow > exceptionHigh)
        {
            exceptionHigh = exceptionNow;
        }

        infolog.add(exceptionNow, enum.currentMessage(), enum.currentHelpUrl(), sysInfoAction, false);
        //infolog.addException(exceptionNow, enum.currentMessage());
    }

    return line;
}

protected boolean checkJournal()
{
    GUPPriceTermJournalTrans journalTrans;
    boolean ret = true;

    ret = ret && journalTable.validateWrite();

    while select journalTrans where journalTrans.AgreementId == journalTable.AgreementId
    {
        setPrefix(errorList.prefixJournalTransLine(journalTrans));

        if (!this.checkTrans(journalTrans))
        {
            errorList.addInfolog(this, journalTrans);

            ret = ret && false;
        }
    }

    this.isValid = ret;

    return ret;
}

protected boolean checkTrans(GUPPriceTermJournalTrans _journalTrans)
{
    boolean ret;

    ret = _journalTrans.validateWrite()
        && this.checkJournalLineOverlap_Internal(_journalTrans, _journalTrans.LineNum)
        && this.checkJournalLineOverlap_External(_journalTrans);

    return ret;
}

protected void updateJournalStatus(GUPDisabledEnabled _status)
{
    GUPPriceTermJournalTable  journalTableToUpdate = GUPPriceTermJournalTable::find(journalTable.AgreementId, true);

    if (journalTableToUpdate.RecId)
    {
        ttsbegin;

        journalTableToUpdate.Status = _status;
        journalTableToUpdate.update();

        ttscommit;
    }
}

private boolean checkJournalLineOverlap_External(GUPPriceTermJournalTrans _journalTrans)
{
    // check journal line with posted price term journal lines.
    GUPPriceTermJournalTable otherJournalTable;
    GUPPriceTermJournalTrans otherJournalTrans;
    GUPPricingRule otherPricingRule;

    GUPPricingRule currentRule = GUPPricingRule::find(_journalTrans.PricingRule);
    GUPPriceTermJournalTable currentJournalTable = GUPPriceTermJournalTable::find(_journalTrans.AgreementId);

    while select otherJournalTrans join otherJournalTable join otherPricingRule
        where otherJournalTrans.AgreementId == otherJournalTable.AgreementId
            && otherJournalTable.AgreementId != this.journalTable.AgreementId
            && otherJournalTable.Status == GUPDisabledEnabled::Enabled
            && otherJournalTable.InventSiteId == currentJournalTable.InventSiteId
            && otherJournalTrans.Code == _journalTrans.Code
            && otherJournalTrans.InventDimId == _journalTrans.InventDimId
            && otherPricingRule.RecId == otherJournalTrans.PricingRule
            && otherPricingRule.PriceAttributeGroupName == currentRule.PriceAttributeGroupName
    {
        if (currentJournalTable.dateRangesOverlap(otherJournalTable)
            && currentRule.rangeOverlap(GUPPricingRule::find(otherJournalTrans.PricingRule)))
        {
            return checkFailed(strFmt(
                "@GlobalUnifiedPricing:GUPJournalCheckPost_PriceTerm_RangeOverlapExternal",
                _journalTrans.LineNum,
                otherJournalTrans.AgreementId,
                otherJournalTrans.LineNum));

        }
    }

    return true;
}

private boolean checkJournalLineOverlap_Internal(GUPPriceTermJournalTrans _journalTrans, LineNum _startIdx = _journalTrans.LineNum)
{
    // check journal line with lines in the same journal.
    GUPPriceTermJournalTrans otherJournalTrans;
    GUPPricingRule otherPricingRule;

    if(_journalTrans.PricingRule)
    {
        GUPPricingRule currentRule = GUPPricingRule::find(_journalTrans.PricingRule);

        while select otherJournalTrans join otherPricingRule
        where otherJournalTrans.AgreementId == this.journalTable.AgreementId
            && otherJournalTrans.PricingRule == otherPricingRule.RecId
            && otherPricingRule.PriceAttributeGroupName == currentRule.PriceAttributeGroupName
            && otherJournalTrans.Code == _journalTrans.Code
            && otherJournalTrans.InventDimId == _journalTrans.InventDimId
            && otherJournalTrans.LineNum > _startIdx
        {
            if (currentRule.rangeOverlap(GUPPricingRule::find(otherJournalTrans.PricingRule)))
            {
                return checkFailed(strFmt(
                "@GlobalUnifiedPricing:GUPJournalCheckPost_PriceTerm_RangeOverlapInternal",
                _journalTrans.LineNum,
                otherJournalTrans.LineNum));
            }
        }
    }
    else
    {
        select firstonly otherJournalTrans
            where otherJournalTrans.AgreementId == this.journalTable.AgreementId
            && otherJournalTrans.PricingRule == _journalTrans.PricingRule
            && otherJournalTrans.Code == _journalTrans.Code
            && otherJournalTrans.InventDimId == _journalTrans.InventDimId
            && otherJournalTrans.LineNum > _startIdx;
        if(otherJournalTrans.RecId)
        {
            return checkFailed(strFmt(
                "@GlobalUnifiedPricing:GUPJournalCheckPost_PriceTerm_RangeOverlapInternal",
                _journalTrans.LineNum,
                otherJournalTrans.LineNum));
        }
    }

    return true;
}
